// Classify each appointment (timezone-aware) and build the right message.
const cfg = $('Configuration').first().json;
const tz = cfg.timezone || 'UTC';
const cc = String(cfg.defaultCountryCode||'').replace(/\D/g,'');
const today = DateTime.now().setZone(tz).startOf('day');
const todayStr = today.toISODate();
const remindDays = cfg.reminderDaysBefore || [1];
const sendWeekends = cfg.sendOnWeekends !== false;
const isWeekend = today.weekday >= 6; // 6=Sat,7=Sun
const fill = (t, c) => String(t||'').replace(/\{(\w+)\}/g, (m,k)=> (c[k] ?? ''));
const validEmail = (e) => /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(String(e||'').trim());
const normPhone = (p) => {
  const raw = String(p||'').trim();
  const hasPlus = raw.startsWith('+');
  let d = raw.replace(/\D/g,'');
  if (hasPlus) return d.length>=8 ? '+'+d : '';
  if (d.startsWith('0')) d = d.slice(1);
  if (cc && !d.startsWith(cc)) d = cc + d;
  return d.length>=10 ? '+'+d : '';
};
const parseDate = (s) => {
  s = String(s||'').trim();
  let d = DateTime.fromISO(s, {zone: tz});
  if (!d.isValid) d = DateTime.fromFormat(s, 'M/d/yyyy', {zone: tz});
  if (!d.isValid) d = DateTime.fromFormat(s.slice(0,10), 'yyyy-MM-dd', {zone: tz});
  return d;
};
const out = [];
for (const row of $input.all()) {
  const j = row.json;
  const id = String(j.AppointmentID || '').trim();
  if (!id) continue;                          // require a unique ID (never append junk rows)
  const status = String(j.Status || '').trim().toLowerCase();
  const appt = parseDate(j.AppointmentDate);
  if (!appt.isValid) continue;                // skip unparseable dates
  const days = Math.round(appt.startOf('day').diff(today, 'days').days);
  const lastToday = String(j.LastContacted || '').slice(0,10) === todayStr;

  let action = 'skip', newStatus = status;
  if (status === 'new')                                              { action='confirm';  newStatus='confirmed'; }
  else if (status === 'confirmed' && remindDays.includes(days) && !lastToday) { action='remind'; newStatus='confirmed'; }
  else if (status === 'no-show')                                     { action='winback';  newStatus='winback-sent'; }
  else if (status === 'completed')                                   { action='review';   newStatus='review-requested'; }
  if (action === 'skip') continue;
  if (isWeekend && !sendWeekends && (action === 'remind' || action === 'review')) continue;

  const t = (cfg.templates || {})[action] || {};
  const c = { name: j.Name || 'there', business: cfg.businessName, date: appt.toFormat('cccc, LLL d'),
              booking: cfg.bookingUrl, review: cfg.reviewUrl, feedback: cfg.feedbackUrl };
  // work out which channels we can actually send on
  let want = String(j.Channel || cfg.channels || 'email').toLowerCase();
  if (want === 'both') want = 'email,sms';
  const email = validEmail(j.Email) ? String(j.Email).trim() : '';
  const phone = normPhone(j.Phone);
  const chans = want.split(',').map(s=>s.trim()).filter(ch => ch==='email' ? email : ch==='sms' ? phone : false);
  if (chans.length === 0) continue;           // nothing we can reach them on — skip cleanly

  out.push({ json: {
    AppointmentID: id, Name: c.name, to: email, phone, channel: chans.join(','),
    AppointmentDate: j.AppointmentDate, action, newStatus, todayStr,
    emailSubject: fill(t.subject, c), emailBody: fill(t.body, c), smsBody: fill(t.sms, c),
    ownerEmail: cfg.ownerEmail, businessName: cfg.businessName
  }});
}
return out;

// One-line daily summary of what was sent.
const items = $input.all();
const cfg = $('Configuration').first().json;
const c = {confirm:0, remind:0, winback:0, review:0};
for (const it of items) c[it.json.action] = (c[it.json.action]||0)+1;
const line = `Confirmations: ${c.confirm} · Reminders: ${c.remind} · No-show win-backs: ${c.winback} · Review requests: ${c.review}`;
return [{ json: {
  total: items.length,
  digestHtml: `<h3>${cfg.businessName} — appointment run</h3><p>${items.length} messages sent.</p><p>${line}</p>`,
  digestText: `*${cfg.businessName}* appointment run\n${items.length} messages sent.\n${line}`,
  ownerEmail: cfg.ownerEmail
} }];
